From c3ae519a88f2f127cfd43c34e000d4b9a90ac2e6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:34:05 +0100
Subject: [PATCH] wallpapers/potd: don't ask about invalid certificates when
 downloading

When a provider's site served an invalid certificate, KIO asked about it
with a widget dialog, which crashed the lock screen greeter and blocked
the wallpaper settings page. Downloads now just fail in that case.

BUG: 526466
BUG: 442912
---
 wallpapers/potd/plugins/providers/apodprovider.cpp           | 2 ++
 wallpapers/potd/plugins/providers/bingprovider.cpp           | 2 ++
 wallpapers/potd/plugins/providers/davidrevoyprovider.cpp     | 2 ++
 wallpapers/potd/plugins/providers/flickrprovider.cpp         | 4 ++++
 wallpapers/potd/plugins/providers/simonstalenhagprovider.cpp | 3 +++
 wallpapers/potd/plugins/providers/wcpotdprovider.cpp         | 2 ++
 6 files changed, 15 insertions(+)

diff --git a/wallpapers/potd/plugins/providers/apodprovider.cpp b/wallpapers/potd/plugins/providers/apodprovider.cpp
index 26fa36146..ae167679a 100644
--- a/wallpapers/potd/plugins/providers/apodprovider.cpp
+++ b/wallpapers/potd/plugins/providers/apodprovider.cpp
@@ -21,6 +21,7 @@ ApodProvider::ApodProvider(QObject *parent, const KPluginMetaData &data, const Q
     QUrl feed_url = QUrl(QStringLiteral("https://science.nasa.gov/wp-json/wp/v2/apod-basic"));

     KIO::StoredTransferJob *job = KIO::storedGet(feed_url, KIO::NoReload, KIO::HideProgressInfo);
+    job->addMetaData(QStringLiteral("ssl_no_ui"), QStringLiteral("true"));
     connect(job, &KIO::StoredTransferJob::finished, this, &ApodProvider::feedRequestFinished);
 }

@@ -56,6 +57,7 @@ void ApodProvider::feedRequestFinished(KJob *_job)
         m_remoteUrl = QUrl(hd_url);

         KIO::StoredTransferJob *imageJob = KIO::storedGet(m_remoteUrl, KIO::NoReload, KIO::HideProgressInfo);
+        imageJob->addMetaData(QStringLiteral("ssl_no_ui"), QStringLiteral("true"));
         connect(imageJob, &KIO::StoredTransferJob::finished, this, &ApodProvider::imageRequestFinished);
     } else {
         Q_EMIT error(this);
